//! `atan2` against Spark 4.2.0: `tests/fixtures/spark-4.2.0/atan2-goldens.tsv`
//! (generated by `tests/scripts/gen_atan2_goldens.py`) holds 1,756 inputs, from
//! zeros, infinities and NaN to ratios beyond 2**60, with the exact doubles
//! Spark's `Math.atan2` (fdlibm) gave. A result must match in every bit; two
//! NaNs match.
//!
//! Not run under Miri: it reads the fixture file, which Miri's isolation forbids.
#![cfg(not(miri))]

use std::path::Path;

use krishiv_kernels::math::BinaryFn;

#[test]
fn atan2_matches_spark_bit_for_bit() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/spark-4.2.0/atan2-goldens.tsv");
    let text = std::fs::read_to_string(path).unwrap();
    let cases: Vec<Vec<f64>> = text
        .lines()
        .map(|l| l.split('\t').map(|v| v.parse::<f64>().unwrap()).collect())
        .collect();
    let parse = |v: &f64| *v;
    let mut wrong = Vec::new();
    for c in &cases {
        let (y, x, want) = (parse(&c[0]), parse(&c[1]), parse(&c[2]));
        let got = BinaryFn::Atan2.apply(y, x).unwrap();
        let same = (got.is_nan() && want.is_nan()) || got.to_bits() == want.to_bits();
        if !same {
            wrong.push(format!("atan2({y:e}, {x:e}) = {got:e}, Spark {want:e}"));
        }
    }
    assert!(
        wrong.is_empty(),
        "{} of {} differ:\n{}",
        wrong.len(),
        cases.len(),
        wrong[..wrong.len().min(15)].join("\n")
    );
}
